static void owner_release(Owner*o){if(!o||--o->refs)return;switch(o->scope){case 0:wm_nfe_client_free(o->client);break;case 1:wm_reseller_client_free(o->client);break;case 2:wm_emitter_client_free(o->client);break;case 3:wm_monitor_client_free(o->client);break;case 4:wm_nfe_files_client_free(o->client);break;default:wm_emitter_files_client_free(o->client);}wm_config_free(o->config);free(o);}
